1	<script lang="ts">
2	  import { onMount } from 'svelte';
3	  import { get } from 'svelte/store';
4	  import { base } from '$app/paths';
5	  import { api } from '$lib/api';
6	  import { notes, todos, settings, activeView, showSettings, syncState, diskFolders, theme,
7	    projects, activeProjectId, taskFilterTag, taskFilterGroupByTags, taskFilterHideUngrouped,
8	    taskFilterToday, draggingTodoId, dragOverToday, activeTimers, focusRequest, projectApplyTick } from '$lib/stores';
9	  import type { Project } from '$lib/types';
10	  import HomeView from '$lib/components/HomeView.svelte';
11	  import TasksView from '$lib/components/TasksView.svelte';
12	  import DocsView from '$lib/components/DocsView.svelte';
13	  import SearchView from '$lib/components/SearchView.svelte';
14	  import SettingsPanel from '$lib/components/SettingsPanel.svelte';
15	  import SyncIndicator from '$lib/components/SyncIndicator.svelte';
16	  import ProjectsNav from '$lib/components/ProjectsNav.svelte';
17	
18	  let autoSyncTimer: ReturnType<typeof setInterval> | null = null;
19	  let loading = $state(true);
20	  let sidebarCollapsed = $state(localStorage.getItem('todoto-sidebar-collapsed') === 'true');
21	  let drawerOpen = $state(false);
22	
23	  function closeDrawer() { drawerOpen = false; }
24	  // Switching to a top-level view clears any applied project filter highlight.
25	  function navMain(id: typeof $activeView) {
26	    activeProjectId.set(null);
27	    // "Today" is a filtered Tasks view rather than its own page.
28	    if (id === 'today') { taskFilterToday.set(true); activeView.set('tasks'); return; }
29	    taskFilterToday.set(false);
30	    activeView.set(id);
31	  }
32	  function isNavActive(id: typeof $activeView) {
33	    if (id === 'today') return $activeView === 'tasks' && $taskFilterToday;
34	    return $activeView === id && !$activeProjectId && !$taskFilterToday;
35	  }
36	
37	  // Dragging a task onto the sidebar "Today" item pins it to today's workload.
38	  // The drop is handled by the pointer-drag logic in TasksView (which finds this
39	  // element via `data-drop-today`); here we only flag it as a valid target.
40	  function navTo(id: typeof $activeView) { navMain(id); closeDrawer(); }
41	
42	  // Tasks with a running timer — one sidebar entry is shown per task so several
43	  // concurrently-logged tasks can each be jumped to.
44	  let liveTasks = $derived($todos.filter((t) => $activeTimers.has(t.id)));
45	
46	  // Jump straight to a running ("live") task in focus mode, from anywhere in the app.
47	  function jumpToTaskFocus(id: string) {
48	    activeView.set('tasks');
49	    focusRequest.set(id);
50	    closeDrawer();
51	  }
52	
53	  // Apply a project shortcut: jump to Tasks, prefiltered to the project's tags.
54	  // The project tags become a hard constraint (handled in TasksView), so we start
55	  // from a clean per-page filter — the user can then filter/group within the project.
56	  function applyProject(p: Project) {
57	    taskFilterTag.set('');
58	    taskFilterGroupByTags.set([]);
59	    taskFilterHideUngrouped.set(false);
60	    taskFilterToday.set(false);
61	    activeProjectId.set(p.id);
62	    activeView.set('tasks');
63	    projectApplyTick.update((n) => n + 1);
64	    closeDrawer();
65	  }
66	
67	  $effect(() => {
68	    localStorage.setItem('todoto-sidebar-collapsed', String(sidebarCollapsed));
69	  });
70	
71	  // ── Theme ─────────────────────────────────────────────────────────────────
72	  function applyTheme(t: 'system' | 'light' | 'dark' | 'midnight' | 'forest') {
73	    const resolved = t === 'system'
74	      ? (window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light')
75	      : t;
76	    document.documentElement.setAttribute('data-theme', resolved);
77	  }
78	
79	  // Initialize from localStorage before first render
80	  const savedTheme = localStorage.getItem('todoto-theme') as 'system' | 'light' | 'dark' | 'midnight' | 'forest' | null;
81	  if (savedTheme) theme.set(savedTheme);
82	  applyTheme(savedTheme ?? 'system');
83	
84	  $effect(() => {
85	    localStorage.setItem('todoto-theme', $theme);
86	    applyTheme($theme);
87	  });
88	
89	  // ── Data loading ──────────────────────────────────────────────────────────
90	  async function loadAll() {
91	    const [n, t, s, f, p] = await Promise.all([api.getNotes(), api.getTodos(), api.getSettings(), api.getFolders(), api.getProjects()]);
92	    notes.set(n);
93	    todos.set(t);
94	    settings.set(s);
95	    diskFolders.set(f);
96	    projects.set(p);
97	    const lastSync = await api.getLastSync();
98	    syncState.update((st) => ({ ...st, lastSync }));
99	    scheduleAutoSync(s.auto_sync, s.sync_interval_seconds);
100	  }
101	
102	  async function refreshNotesFromDisk() {
103	    const [fresh, folders] = await Promise.all([api.getNotes(), api.getFolders()]);
104	    diskFolders.set(folders);
105	    notes.update((current) => {
106	      const byId = new Map(current.map((n) => [n.id, n]));
107	      for (const n of fresh) {
108	        const existing = byId.get(n.id);
109	        if (!existing || n.updated_at > existing.updated_at) byId.set(n.id, n);
110	      }
111	      return [...byId.values()].sort(
112	        (a, b) => Number(b.pinned) - Number(a.pinned) || b.updated_at.localeCompare(a.updated_at)
113	      );
114	    });
115	  }
116	
117	  function scheduleAutoSync(enabled: boolean, intervalSecs: number) {
118	    if (autoSyncTimer) clearInterval(autoSyncTimer);
119	    if (!enabled || intervalSecs <= 0) return;
120	    autoSyncTimer = setInterval(triggerSync, intervalSecs * 1000);
121	  }
122	
123	  async function triggerSync() {
124	    syncState.update((s) => ({ ...s, syncing: true }));
125	    try {
126	      const result = await api.syncNow();
127	      const [n, t, f, p] = await Promise.all([api.getNotes(), api.getTodos(), api.getFolders(), api.getProjects()]);
128	      notes.set(n); todos.set(t); diskFolders.set(f); projects.set(p);
129	      // Only advance lastSync on success — a failed attempt must not be shown as
130	      // the last sync time.
131	      syncState.update((s) => ({ syncing: false, lastResult: result, lastSync: result.success ? result.timestamp : s.lastSync }));
132	    } catch {
133	      syncState.update((s) => ({ ...s, syncing: false }));
134	    }
135	  }
136	
137	  function handleKeydown(e: KeyboardEvent) {
138	    if (e.ctrlKey && e.key === 's') { e.preventDefault(); triggerSync(); }
139	  }
140	
141	  onMount(() => {
142	    loadAll().finally(() => { loading = false; });
143	    const onFocus = () => void refreshNotesFromDisk();
144	    const mq = window.matchMedia('(prefers-color-scheme: dark)');
145	    const onSystemChange = () => { if (get(theme) === 'system') applyTheme('system'); };
146	    window.addEventListener('keydown', handleKeydown);
147	    window.addEventListener('focus', onFocus);
148	    mq.addEventListener('change', onSystemChange);
149	    return () => {
150	      if (autoSyncTimer) clearInterval(autoSyncTimer);
151	      window.removeEventListener('keydown', handleKeydown);
152	      window.removeEventListener('focus', onFocus);
153	      mq.removeEventListener('change', onSystemChange);
154	    };
155	  });
156	
157	  // ── Nav ───────────────────────────────────────────────────────────────────
158	  const navItems = [
159	    { id: 'home'   as const, label: 'Home',   svg: svgHome   },
160	    { id: 'tasks'  as const, label: 'Tasks',  svg: svgTasks  },
161	    { id: 'today'  as const, label: 'Today',  svg: svgToday  },
162	    { id: 'docs'   as const, label: 'Docs',   svg: svgDocs   },
163	    { id: 'search' as const, label: 'Search', svg: svgSearch },
164	  ];
165	
166	  // All nav SVGs use currentColor so CSS drives active/inactive tinting
167	  function svgHome() {
168	    return `<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 9l9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><polyline points="9 22 9 12 15 12 15 22"/></svg>`;
169	  }
170	  function svgTasks() {
171	    return `<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M9 11l3 3L22 4"/><path d="M21 12v7a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11"/></svg>`;
172	  }
173	  function svgToday() {
174	    return `<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="5"/><line x1="12" y1="1" x2="12" y2="3"/><line x1="12" y1="21" x2="12" y2="23"/><line x1="4.22" y1="4.22" x2="5.64" y2="5.64"/><line x1="18.36" y1="18.36" x2="19.78" y2="19.78"/><line x1="1" y1="12" x2="3" y2="12"/><line x1="21" y1="12" x2="23" y2="12"/><line x1="4.22" y1="19.78" x2="5.64" y2="18.36"/><line x1="18.36" y1="5.64" x2="19.78" y2="7.05"/></svg>`;
175	  }
