import puppeteer from 'puppeteer-core';

const OUT = '/tmp/claude-1000/-home-joachim-git-4less-todoto/0d69ca72-e954-4259-ad6e-0b3120b069c8/scratchpad';
const URL_ = 'http://localhost:1420';
const browser = await puppeteer.launch({
  executablePath: '/usr/bin/google-chrome',
  headless: 'new',
  args: ['--no-sandbox', '--disable-dev-shm-usage'],
  defaultViewport: { width: 1400, height: 900 },
});
const page = await browser.newPage();
const errors = [];
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function clickText(sel, text) {
  const ok = await page.evaluate((sel, text) => {
    const el = [...document.querySelectorAll(sel)].find((e) => e.textContent.includes(text));
    if (!el) return false;
    el.click();
    return true;
  }, sel, text);
  if (!ok) throw new Error(`no ${sel} containing "${text}"`);
  await sleep(300);
}
const nodeBox = (i) => page.evaluate((i) => {
  const n = [...document.querySelectorAll('.node')][i];
  const r = n.getBoundingClientRect();
  return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
}, i);
const geom = () => page.evaluate(() =>
  [...document.querySelectorAll('.node')].map((n) => ({
    x: parseFloat(n.style.left), y: parseFloat(n.style.top),
    w: parseFloat(n.style.width), h: parseFloat(n.style.height),
  })));
const panningClass = () => page.evaluate(() =>
  document.querySelector('.canvas').classList.contains('panning'));
const cursor = () => page.evaluate(() =>
  getComputedStyle(document.querySelector('.canvas')).cursor);

// Seed: reference node at a deliberately off-grid position.
await page.goto(URL_, { waitUntil: 'networkidle2' });
await page.evaluate(() => {
  const now = new Date().toISOString();
  localStorage.setItem('todoto-idb-projects', JSON.stringify({
    projects: [{ id: 'p1', name: 'Demo', tags: ['demo'], icon: '', color: '#6366f1' }],
    version: 1, updated_at: now,
  }));
  localStorage.setItem('todoto-idb-whiteboards', JSON.stringify({
    whiteboards: [{
      id: 'wb1', name: 'Snap check', tags: ['demo'],
      nodes: [
        { id: 'ref', kind: 'rect', x: 500, y: 170, w: 200, h: 100, text: 'reference', color: 'blue' },
        { id: 'mov', kind: 'sticky', x: 300, y: 430, w: 160, h: 140, text: 'move me', color: 'yellow' },
      ],
      edges: [], created_at: now, updated_at: now,
    }],
    version: 1,
  }));
});
await page.goto(URL_, { waitUntil: 'networkidle2' });
await sleep(1200);
await clickText('button', 'Demo');
await sleep(400);
await clickText('.wb-open', 'Snap check');
await sleep(600);

// ── A. right-click then dismiss must not leave a stuck drag ─────────────────
console.log('A) cursor before right-click:', await cursor(), '| panning:', await panningClass());
await page.mouse.click(1150, 300, { button: 'right' });
await sleep(400);
console.log('   after right-click  -> panning:', await panningClass(), '| cursor:', await cursor());
// Dismiss with a left click elsewhere, as the user described.
await page.mouse.click(1000, 700);
await sleep(400);
console.log('   after dismiss click-> panning:', await panningClass(), '| cursor:', await cursor());
// And a bare pointer move afterwards must not pan the canvas.
const panBefore = await page.evaluate(() => document.querySelector('.world').style.transform);
await page.mouse.move(700, 500, { steps: 8 });
await sleep(300);
const panAfter = await page.evaluate(() => document.querySelector('.world').style.transform);
console.log('   canvas drifted on hover:', panBefore !== panAfter);

// ── B. plain drag (no Ctrl) stays free-form / off-grid ──────────────────────
let box = await nodeBox(1);
await page.mouse.move(box.x, box.y);
await page.mouse.down();
await page.mouse.move(box.x + 53, box.y - 97, { steps: 12 });
await page.mouse.up();
await sleep(300);
let g = await geom();
console.log('B) free drag ->', JSON.stringify(g[1]), '| on 24px grid:', g[1].x % 24 === 0 && g[1].y % 24 === 0);

// ── C. Ctrl-drag into open space snaps to the 24px grid ────────────────────
box = await nodeBox(1);
await page.keyboard.down('Control');
await page.mouse.move(box.x, box.y);
await page.mouse.down();
await page.mouse.move(box.x - 137, box.y + 111, { steps: 12 });
const guidesMid = await page.evaluate(() => document.querySelectorAll('.guide').length);
await page.mouse.up();
await page.keyboard.up('Control');
await sleep(300);
g = await geom();
console.log('C) ctrl drag ->', JSON.stringify(g[1]),
  '| on grid:', g[1].x % 24 === 0 && g[1].y % 24 === 0, '| guides mid-drag:', guidesMid);

// ── D. Ctrl-drag near the reference node snaps to ITS edges, not the grid ──
// Aim the moving node's left edge just shy of the reference's left edge (500).
const ref = (await geom())[0];
box = await nodeBox(1);
let cur = await geom();
const wantLeft = ref.x + 3;            // 3px off — inside tolerance, off-grid
const wantTop = ref.y + ref.h + 40;
await page.keyboard.down('Control');
await page.mouse.move(box.x, box.y);
await page.mouse.down();
await page.mouse.move(box.x + (wantLeft - cur[1].x), box.y + (wantTop - cur[1].y), { steps: 14 });
const guideCount = await page.evaluate(() => document.querySelectorAll('.guide').length);
await page.mouse.up();
await page.keyboard.up('Control');
await sleep(300);
g = await geom();
console.log('D) ref.x =', ref.x, '| snapped x =', g[1].x, '| aligned to ref left:', g[1].x === ref.x,
  '| guides shown:', guideCount);

// ── E. Ctrl-resize snaps the far edge ──────────────────────────────────────
box = await nodeBox(1);
await page.mouse.click(box.x, box.y);
await sleep(300);
const handle = await page.evaluate(() => {
  const h = document.querySelector('.resize-handle');
  const r = h.getBoundingClientRect();
  return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
});
const sizeBefore = (await geom())[1];
await page.keyboard.down('Control');
await page.mouse.move(handle.x, handle.y);
await page.mouse.down();
await page.mouse.move(handle.x + 67, handle.y + 43, { steps: 12 });
await page.mouse.up();
await page.keyboard.up('Control');
await sleep(300);
g = await geom();
const right = g[1].x + g[1].w, bottom = g[1].y + g[1].h;
console.log('E) resize', `${sizeBefore.w}x${sizeBefore.h}`, '->', `${g[1].w}x${g[1].h}`,
  '| right edge', right, 'on grid:', right % 24 === 0,
  '| bottom edge', bottom, 'on grid:', bottom % 24 === 0);

// ── F. guides cleared after the drag ends ──────────────────────────────────
console.log('F) guides after drag end:', await page.evaluate(() => document.querySelectorAll('.guide').length));

// ── G. the dot grid tracks pan and zoom ────────────────────────────────────
const bgBefore = await page.evaluate(() => {
  const s = getComputedStyle(document.querySelector('.canvas'));
  return s.backgroundPosition + ' / ' + s.backgroundSize;
});
await page.mouse.move(1200, 250);
await page.mouse.down();
await page.mouse.move(1100, 330, { steps: 10 });
await page.mouse.up();
await clickText('button[aria-label="Zoom in"]', '');
await sleep(300);
const bgAfter = await page.evaluate(() => {
  const s = getComputedStyle(document.querySelector('.canvas'));
  return s.backgroundPosition + ' / ' + s.backgroundSize;
});
console.log('G) grid before:', bgBefore, '| after pan+zoom:', bgAfter, '| tracks:', bgBefore !== bgAfter);

// Screenshot with guides visible mid-drag.
box = await nodeBox(1);
cur = await geom();
await page.keyboard.down('Control');
await page.mouse.move(box.x, box.y);
await page.mouse.down();
await page.mouse.move(box.x + 40, box.y - 120, { steps: 10 });
await page.screenshot({ path: `${OUT}/snap-guides.png` });
await page.mouse.up();
await page.keyboard.up('Control');

console.log('CONSOLE ERRORS:', errors.length ? JSON.stringify(errors, null, 2) : 'none');
await browser.close();

