import puppeteer from 'puppeteer-core';

const OUT = '/tmp/claude-1000/-home-joachim-git-4less-todoto/0d69ca72-e954-4259-ad6e-0b3120b069c8/scratchpad';
const URL_ = 'http://localhost:1420';
const browser = await puppeteer.launch({
  executablePath: '/usr/bin/google-chrome',
  headless: 'new',
  args: ['--no-sandbox', '--disable-dev-shm-usage'],
  defaultViewport: { width: 1400, height: 900 },
});
const page = await browser.newPage();
const errors = [];
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

async function clickText(sel, text) {
  const ok = await page.evaluate((sel, text) => {
    const el = [...document.querySelectorAll(sel)].find((e) => e.textContent.includes(text));
    if (!el) return false;
    el.click();
    return true;
  }, sel, text);
  if (!ok) throw new Error(`no ${sel} containing "${text}"`);
  await sleep(300);
}
const dblclick = async (x, y) => {
  await page.mouse.move(x, y);
  await page.mouse.down({ clickCount: 1 }); await page.mouse.up({ clickCount: 1 });
  await sleep(30);
  await page.mouse.down({ clickCount: 2 }); await page.mouse.up({ clickCount: 2 });
};
const nodeBox = (i) => page.evaluate((i) => {
  const n = [...document.querySelectorAll('.node')][i];
  const r = n.getBoundingClientRect();
  return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
}, i);
// Compact board state: what undo/redo is supposed to restore.
const state = () => page.evaluate(() => ({
  nodes: [...document.querySelectorAll('.node')].map((n) => ({
    x: parseFloat(n.style.left), y: parseFloat(n.style.top),
    w: parseFloat(n.style.width), h: parseFloat(n.style.height),
    text: n.innerText.trim().split('\n')[0],
    fill: n.style.getPropertyValue('--node-fill').trim(),
  })),
  edges: document.querySelectorAll('svg.edges line.edge').length,
  name: document.querySelector('.name')?.textContent.trim(),
}));
const buttons = () => page.evaluate(() => ({
  undo: !document.querySelector('button[aria-label="Undo"]').disabled,
  redo: !document.querySelector('button[aria-label="Redo"]').disabled,
}));
const undo = async (n = 1) => { for (let i = 0; i < n; i++) { await page.keyboard.down('Control'); await page.keyboard.press('KeyZ'); await page.keyboard.up('Control'); await sleep(200); } };
const redo = async (n = 1) => { for (let i = 0; i < n; i++) { await page.keyboard.down('Control'); await page.keyboard.down('Shift'); await page.keyboard.press('KeyZ'); await page.keyboard.up('Shift'); await page.keyboard.up('Control'); await sleep(200); } };
const eq = (a, b) => JSON.stringify(a) === JSON.stringify(b);

await page.goto(URL_, { waitUntil: 'networkidle2' });
await page.evaluate(() => {
  const now = new Date().toISOString();
  localStorage.setItem('todoto-idb-projects', JSON.stringify({
    projects: [{ id: 'p1', name: 'Demo', tags: ['demo'], icon: '', color: '#6366f1' }],
    version: 1, updated_at: now,
  }));
  localStorage.setItem('todoto-idb-whiteboards', JSON.stringify({
    whiteboards: [{
      id: 'wb1', name: 'Undo check', tags: ['demo'],
      nodes: [
        { id: 'a', kind: 'sticky', x: 300, y: 200, w: 180, h: 150, text: 'alpha', color: 'yellow' },
        { id: 'b', kind: 'rect', x: 620, y: 420, w: 200, h: 110, text: 'beta', color: 'blue' },
      ],
      edges: [], created_at: now, updated_at: now,
    }],
    version: 1,
  }));
});
await page.goto(URL_, { waitUntil: 'networkidle2' });
await sleep(1200);
await clickText('button', 'Demo');
await clickText('.wb-open', 'Undo check');
await sleep(600);

const s0 = await state();
console.log('0) initial:', JSON.stringify(s0));
console.log('   buttons at start (both should be false):', JSON.stringify(await buttons()));

// ── 1. MOVE: one entry per gesture, not per pointermove ────────────────────
let box = await nodeBox(0);
await page.mouse.move(box.x, box.y);
await page.mouse.down();
for (let i = 1; i <= 12; i++) await page.mouse.move(box.x + i * 10, box.y + i * 6);
await page.mouse.up();
await sleep(300);
const sMoved = await state();
console.log('1) moved to', sMoved.nodes[0].x, sMoved.nodes[0].y, '| undo enabled:', (await buttons()).undo);
await undo();
console.log('   after 1 undo -> back to start:', eq(await state(), s0), '(12 moves = 1 entry)');
await redo();
console.log('   after redo   -> back to moved:', eq(await state(), sMoved));

// ── 2. RESIZE coalesces too ────────────────────────────────────────────────
box = await nodeBox(0);
await page.mouse.click(box.x, box.y);
await sleep(250);
const handle = await page.evaluate(() => {
  const h = document.querySelector('.resize-handle');
  const r = h.getBoundingClientRect();
  return { x: r.x + r.width / 2, y: r.y + r.height / 2 };
});
await page.mouse.move(handle.x, handle.y);
await page.mouse.down();
for (let i = 1; i <= 10; i++) await page.mouse.move(handle.x + i * 8, handle.y + i * 5);
await page.mouse.up();
await sleep(300);
const sResized = await state();
console.log('2) resized to', sResized.nodes[0].w + 'x' + sResized.nodes[0].h);
await undo();
console.log('   after 1 undo -> size restored:', eq(await state(), sMoved));
await redo();
console.log('   redo ok:', eq(await state(), sResized));

// ── 3. TEXT: a whole editing session is one entry ──────────────────────────
box = await nodeBox(0);
await dblclick(box.x, box.y);
await sleep(300);
await page.keyboard.down('Control'); await page.keyboard.press('KeyA'); await page.keyboard.up('Control');
await page.keyboard.type('rewritten');
await page.mouse.click(1150, 800);
await sleep(400);
const sText = await state();
console.log('3) text now:', sText.nodes[0].text);
await undo();
console.log('   after 1 undo -> text restored:', (await state()).nodes[0].text,
  '| whole state matches:', eq(await state(), sResized));
await redo();
console.log('   redo ok:', eq(await state(), sText));

// ── 4. COLOUR ──────────────────────────────────────────────────────────────
box = await nodeBox(0);
await page.mouse.click(box.x, box.y);
await sleep(250);
await page.evaluate(() => document.querySelectorAll('.inspector .swatch')[4].click());
await sleep(300);
const sColor = await state();
console.log('4) fill now:', sColor.nodes[0].fill);
await undo();
console.log('   after undo -> fill:', (await state()).nodes[0].fill, '| matches:', eq(await state(), sText));

// ── 5. ADD, CONNECT, DELETE ────────────────────────────────────────────────
await clickText('button', 'Sticky');
await sleep(300);
await page.keyboard.type('third');
await page.mouse.click(1150, 800);
await sleep(400);
console.log('5) node count after add:', (await state()).nodes.length);

await clickText('button', 'Connect');
let c0 = await nodeBox(0), c1 = await nodeBox(1);
await page.mouse.click(c0.x, c0.y); await sleep(200);
await page.mouse.click(c1.x, c1.y); await sleep(300);
const sConnected = await state();
console.log('   edges after connect:', sConnected.edges);
await undo();
console.log('   undo connect -> edges:', (await state()).edges);
await redo();
console.log('   redo connect -> edges:', (await state()).edges);

// Delete a node; its edge must come back with it on undo.
c0 = await nodeBox(0);
await page.mouse.click(c0.x, c0.y);
await sleep(250);
await page.keyboard.press('Delete');
await sleep(300);
const sDeleted = await state();
console.log('   after delete -> nodes:', sDeleted.nodes.length, 'edges:', sDeleted.edges);
await undo();
const sBack = await state();
console.log('   undo delete -> nodes:', sBack.nodes.length, 'edges:', sBack.edges,
  '| fully restored:', eq(sBack, sConnected));

// ── 6. A new edit clears the redo stack ────────────────────────────────────
await undo();
console.log('6) redo available after undo:', (await buttons()).redo);
await clickText('button', 'Rectangle');
await sleep(300);
await page.mouse.click(1150, 800);
await sleep(300);
console.log('   redo available after a new edit:', (await buttons()).redo, '(should be false)');

// ── 7. Undo past the beginning is a no-op, and survives persistence ────────
await undo(40);
const sFinal = await state();
console.log('7) after 40 undos -> nodes:', sFinal.nodes.length, '| undo btn enabled:', (await buttons()).undo);
console.log('   matches original board:', eq(sFinal, s0));

await sleep(700);
await page.goto(URL_, { waitUntil: 'networkidle2' });
await sleep(1200);
await clickText('button', 'Demo');
await clickText('.wb-open', 'Undo check');
await sleep(600);
console.log('   persisted after reload:', JSON.stringify(await state()));
console.log('   history cleared on reopen:', JSON.stringify(await buttons()));
await page.screenshot({ path: `${OUT}/undo-final.png` });

console.log('CONSOLE ERRORS:', errors.length ? JSON.stringify(errors, null, 2) : 'none');
await browser.close();

