import puppeteer from 'puppeteer-core';

const OUT = '/tmp/claude-1000/-home-joachim-git-4less-todoto/0d69ca72-e954-4259-ad6e-0b3120b069c8/scratchpad';
const URL_ = 'http://localhost:1420';
const browser = await puppeteer.launch({
  executablePath: '/usr/bin/google-chrome', headless: 'new',
  args: ['--no-sandbox', '--disable-dev-shm-usage'], defaultViewport: { width: 1400, height: 900 },
});
const page = await browser.newPage();
const errors = [];
page.on('console', (m) => { if (m.type() === 'error') errors.push(m.text()); });
page.on('pageerror', (e) => errors.push('PAGEERROR: ' + e.message));
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const clickText = async (sel, text) => {
  const ok = await page.evaluate((s, t) => {
    const el = [...document.querySelectorAll(s)].find((e) => e.textContent.includes(t));
    if (!el) return false; el.click(); return true;
  }, sel, text);
  if (!ok) throw new Error(`no ${sel} with "${text}"`);
  await sleep(350);
};
const menu = () => page.evaluate(() => ({
  rows: [...document.querySelectorAll('.menu .row')].map((r) => r.innerText.replace(/\s+/g, ' ').trim()),
  hasNew: !!document.querySelector('.menu .row.create'),
  newBadge: document.querySelector('.menu .new-badge')?.textContent?.trim() ?? null,
  near: [...document.querySelectorAll('.menu .near-tag')].map((n) => n.textContent.trim()),
}));
const chips = () => page.evaluate(() =>
  [...document.querySelectorAll('.tag-input .chip')].map((c) => c.textContent.replace('✕', '').trim()));

// Seed items carrying deliberately messy tag spellings.
await page.goto(URL_, { waitUntil: 'networkidle2' });
await page.evaluate(() => {
  const now = new Date().toISOString();
  const todo = (id, title, tags) => ({
    id, title, done: false, priority: 'none', due_date: null, tags,
    created_at: now, updated_at: now, started_at: null, finished_at: null, work_sessions: [],
  });
  localStorage.setItem('todoto-idb-projects', JSON.stringify({ projects: [], version: 1, updated_at: now }));
  localStorage.setItem('todoto-idb-tags', JSON.stringify({ tags: [], version: 1, updated_at: '' }));
  localStorage.setItem('todoto-idb-whiteboards', JSON.stringify({ whiteboards: [], version: 1 }));
  window.__seed = [
    todo('t1', 'Task one', ['ProtalDev']),
    todo('t2', 'Task two', ['protal_dev']),
    todo('t3', 'Task three', ['PROTAL-DEV']),
    todo('t4', 'Task four', ['kubernetes']),
    todo('t5', 'Task five', ['k8s']),
    todo('t6', 'Task six', ['kubernetes']),
  ];
});
// Write seeds straight into IndexedDB so the app loads them as real todos.
await page.evaluate(async () => {
  const db = await new Promise((res, rej) => {
    const r = indexedDB.open('todoto', 1);
    r.onupgradeneeded = (e) => {
      const d = e.target.result;
      if (!d.objectStoreNames.contains('notes')) d.createObjectStore('notes', { keyPath: 'id' });
      if (!d.objectStoreNames.contains('todos')) d.createObjectStore('todos', { keyPath: 'id' });
      if (!d.objectStoreNames.contains('images')) d.createObjectStore('images', { keyPath: 'path' });
    };
    r.onsuccess = () => res(r.result); r.onerror = () => rej(r.error);
  });
  await new Promise((res) => {
    const tx = db.transaction('todos', 'readwrite');
    for (const t of window.__seed) tx.objectStore('todos').put(t);
    tx.oncomplete = res;
  });
});
await page.goto(URL_, { waitUntil: 'networkidle2' });
await sleep(1500);
await clickText('button', 'Tasks');
await sleep(500);

// ── 1. Case/separator variants collapse automatically ──────────────────────
await clickText('button.fab', '');
await sleep(400);
await page.click('.tag-input .entry');
await sleep(300);
let m = await menu();
console.log('1) suggestions with no input:', JSON.stringify(m.rows));
const protalRows = m.rows.filter((r) => /protal/i.test(r));
console.log('   ProtalDev/protal_dev/PROTAL-DEV collapsed to one row:', protalRows.length === 1, protalRows);
console.log('   count shown (3 items share it):', protalRows[0]);

// ── 2. Typing an existing tag: no NEW badge ────────────────────────────────
await page.type('.tag-input .entry', 'protal_dev');
await sleep(350);
m = await menu();
console.log('2) typing "protal_dev" → NEW offered:', m.hasNew, '(should be false — it already exists)');
console.log('   matched row:', m.rows[0]);

// ── 3. Typing a genuinely new tag: NEW badge appears ───────────────────────
await page.evaluate(() => { document.querySelector('.tag-input .entry').value = ''; });
await page.click('.tag-input .entry', { clickCount: 3 });
await page.keyboard.press('Backspace');
await page.type('.tag-input .entry', 'analytics');
await sleep(350);
m = await menu();
console.log('3) typing "analytics" → NEW offered:', m.hasNew, '| badge:', m.newBadge);

// ── 4. Near-miss warning on a typo ─────────────────────────────────────────
for (let i = 0; i < 20; i++) await page.keyboard.press('Backspace');
await page.type('.tag-input .entry', 'kubernets');
await sleep(400);
m = await menu();
console.log('4) typo "kubernets" → NEW:', m.hasNew, '| similar existing shown:', JSON.stringify(m.near));

// ── 5. Selecting a suggestion stores the canonical spelling ────────────────
for (let i = 0; i < 20; i++) await page.keyboard.press('Backspace');
await page.type('.tag-input .entry', 'PROTAL-DEV');
await sleep(350);
await page.keyboard.press('Enter');
await sleep(300);
console.log('5) typed "PROTAL-DEV" → chip stored as:', JSON.stringify(await chips()));

await page.screenshot({ path: `${OUT}/tag-autocomplete.png` });

// ── 6. Curation: merge k8s into kubernetes, rewriting items ────────────────
await page.keyboard.press('Escape');
await sleep(200);
await clickText('.settings-btn', 'Tags');
await sleep(600);
const before = await page.evaluate(() =>
  [...document.querySelectorAll('.tag-row')].map((r) => r.innerText.replace(/\s+/g, ' ').trim()));
console.log('6) tag rows:', JSON.stringify(before, null, 0));
const dupeShown = await page.evaluate(() => !!document.querySelector('.dupes'));
console.log('   duplicate suggestions surfaced:', dupeShown);

await page.screenshot({ path: `${OUT}/tag-manager.png` });

// Merge k8s → kubernetes via the row actions.
await page.evaluate(() => {
  const row = [...document.querySelectorAll('.tag-row')].find((r) => r.innerText.startsWith('#k8s'));
  [...row.querySelectorAll('button')].find((b) => b.textContent.includes('merge…')).click();
});
await sleep(300);
await page.evaluate(() => {
  const row = [...document.querySelectorAll('.tag-row')].find((r) => r.innerText.startsWith('#kubernetes'));
  [...row.querySelectorAll('button')].find((b) => b.textContent.includes('merge here')).click();
});
await sleep(1200);
const after = await page.evaluate(() =>
  [...document.querySelectorAll('.tag-row')].map((r) => r.innerText.replace(/\s+/g, ' ').trim()));
console.log('   after merge:', JSON.stringify(after));

const stored = await page.evaluate(async () => {
  const db = await new Promise((res) => { const r = indexedDB.open('todoto', 1); r.onsuccess = () => res(r.result); });
  const all = await new Promise((res) => {
    const req = db.transaction('todos').objectStore('todos').getAll();
    req.onsuccess = () => res(req.result);
  });
  return all.map((t) => ({ title: t.title, tags: t.tags }));
});
console.log('   todos rewritten on disk:', JSON.stringify(stored.filter((t) => /four|five|six/.test(t.title))));
console.log('   registry:', await page.evaluate(() => localStorage.getItem('todoto-idb-tags')));

// ── 7. The merged alias now autocompletes to the canonical tag ─────────────
await page.evaluate(() => document.querySelector('.panel .close').click());
await sleep(400);
await clickText('button.fab', '');
await sleep(400);
await page.click('.tag-input .entry');
await page.type('.tag-input .entry', 'k8s');
await sleep(400);
m = await menu();
console.log('7) typing alias "k8s" → NEW offered:', m.hasNew, '(should be false) | row:', m.rows[0]);
await page.keyboard.press('Enter');
await sleep(300);
console.log('   chip stored as:', JSON.stringify(await chips()));

console.log('CONSOLE ERRORS:', errors.length ? JSON.stringify(errors, null, 2) : 'none');
await browser.close();

