/**
 * The distinct spellings actually stored on items for a given tag. More than one
 * means older items still carry a variant: they're the same tag conceptually,
 * but code that compares raw strings (filters, project scoping, grouping) would
 * treat them as different until they're unified.
 */
export function storedVariants(
  tag: Tag,
  todos: Todo[],
  notes: Note[],
  boards: Whiteboard[]
): string[] {
  const keys = new Set(keysOf(tag));
  const seen = new Map<string, string>();
  for (const item of [...todos, ...notes, ...boards]) {
    for (const raw of item.tags) {
      const k = tagKey(raw);
      if (keys.has(k) && !seen.has(raw)) seen.set(raw, raw);
    }
  }
  return [...seen.values()];
}

/** True for entries synthesised by allTags() rather than stored in the registry. */

/**
 * Rewrites every item carrying a variant spelling to the canonical one. New
 * input is canonicalized on the way in, so this is only ever needed for items
 * that predate the tag being curated.
 */
async function unifySpellings(t: Tag) {
  busy = true;
  try {
    const keys = new Set(keysOf(t));
    await rewriteItems((list) => {
      const out: string[] = [];
      const seen = new Set<string>();
      for (const raw of list) {
        const mapped = keys.has(tagKey(raw)) ? t.canonical : raw;
        if (seen.has(tagKey(mapped))) continue;
        seen.add(tagKey(mapped));
        out.push(mapped);
      }
      return out;
    });
  } finally {
    busy = false;
  }
}

